import{_ as e,o as t,c as o,a2 as a}from"./chunks/framework.BBd5PKnH.js";const i="/dev-notes/assets/Screenshot%202026-09-27%20at%2018.28.43.BMgTbFTL.png",r="/dev-notes/assets/Screenshot%202026-09-27%20at%2018.41.57.DUx3rpHk.png",u=JSON.parse('{"title":"Semantic Versioning (SemVer)","description":"","frontmatter":{},"headers":[],"relativePath":"notes/semantic-versoning.md","filePath":"notes/semantic-versoning.md"}'),c={name:"notes/semantic-versoning.md"};function s(h,n,g,l,d,p){return t(),o("div",null,[...n[0]||(n[0]=[a('<h1 id="semantic-versioning-semver" tabindex="-1">Semantic Versioning (SemVer) <a class="header-anchor" href="#semantic-versioning-semver" aria-label="Permalink to &quot;Semantic Versioning (SemVer)&quot;">​</a></h1><blockquote><p>Tham khảo: <a href="https://www.youtube.com/watch?v=33CwoRO6-GE&amp;list=PLoaAbmGPgTSPSuyBWGJ9PfatrBvUTeMPL&amp;index=5" target="_blank" rel="noreferrer">video giải thích Semantic Versioning</a></p></blockquote><p>Một version theo chuẩn SemVer có dạng <code>MAJOR.MINOR.PATCH</code>, ví dụ <code>4.17.1</code>:</p><p><img src="'+i+'" alt="Ví dụ version patch/minor/major"></p><ul><li><strong>Patch</strong> (<code>4.17.1</code> → <code>4.17.2</code>): tăng lên mỗi lần release sau khi fix được bug, không thêm tính năng mới.</li><li><strong>Minor</strong> (<code>4.17.x</code> → <code>4.18.0</code>): release feature mới nhưng <strong>không</strong> thay đổi API hiện tại, không phá vỡ (break) functionality đang có.</li><li><strong>Major</strong> (<code>4.x.x</code> → thay đổi version đầu): release feature mới làm thay đổi cả API lẫn functionality của app. Ví dụ: thay đổi trên endpoint (bổ sung thêm tham số bắt buộc...) khiến các app phụ thuộc vào nó phải cập nhật code nhiều hơn khi nâng cấp lên version này.</li></ul><h2 id="ky-hieu-range-trong-package-json" tabindex="-1">Ký hiệu range trong package.json <a class="header-anchor" href="#ky-hieu-range-trong-package-json" aria-label="Permalink to &quot;Ký hiệu range trong package.json&quot;">​</a></h2><p><img src="'+r+'" alt="Ký hiệu ^ và ~"></p><ul><li><strong><code>^</code> (caret)</strong>: giữ nguyên MAJOR, cho phép tự động cập nhật lên MINOR + PATCH cao nhất/mới nhất.</li><li><strong><code>~</code> (tilde)</strong>: chỉ cho phép tự động cập nhật PATCH.</li></ul><h2 id="nen-dung-cach-nao" tabindex="-1">Nên dùng cách nào? <a class="header-anchor" href="#nen-dung-cach-nao" aria-label="Permalink to &quot;Nên dùng cách nào?&quot;">​</a></h2><ul><li>Nếu app đã chạy ổn định, nên <strong>fix cứng version</strong> (không dùng <code>^</code>/<code>~</code>) để tránh rủi ro.</li><li>Nếu để tự động cập nhật minor/patch, có thể vô tình kéo theo bug mới từ các bản release sau — cần cân nhắc đánh đổi giữa việc tự động nhận bản vá và rủi ro phát sinh lỗi không lường trước.</li></ul>',10)])])}const v=e(c,[["render",s]]);export{u as __pageData,v as default};
